#include <iostream>
#include <iomanip> // For setting output precision and alignment

using namespace std;

int main() {
    double baseA, baseB, height;
    double area;

    // Prompt the user for input
    cout << "=== Trapezoid Area Calculator ===" << endl << endl;
    cout << "Please enter the following values:" << endl;

    cout << "Enter the length of the longer base: ";
    if (!(cin >> baseA)) {
        cerr << "Error: Invalid input for base A. Please enter a numeric value." << endl;
        return 1;
    }

    cout << "Enter the length of the shorter base: ";
    if (!(cin >> baseB)) {
        cerr << "Error: Invalid input for base B. Please enter a numeric value." << endl;
        return 1;
    }

    cout << "Enter the height: ";
    if (!(cin >> height)) {
        cerr << "Error: Invalid input for height. Please enter a numeric value." << endl;
        return 1;
    }

    // Validate that dimensions are positive (geometry implies positive lengths)
    if (baseA <= 0 || baseB <= 0 || height <= 0) {
        cout << endl << "Error: Dimensions must be strictly positive numbers." << endl;
        return 1;
    }

    // Calculate the area
    // Formula: Area = (baseA + baseB) * height / 2
    area = (baseA + baseB) * height / 2.0;

    // Output the results in a clear, formatted manner
    cout << endl;
    cout << "-----------------------------" << endl;
    cout << "|       CALCULATION REPORT   |" << endl;
    cout << "-----------------------------" << endl;
    cout << endl;
    cout << "Entered Dimensions:" << endl;
    cout << "  Longer Base (a): " << setw(10) << fixed << setprecision(2) << baseA << endl;
    cout << "  Shorter Base (b): " << setw(10) << fixed << setprecision(2) << baseB << endl;
    cout << "  Height (h):        " << setw(10) << fixed << setprecision(2) << height << endl;
    cout << endl;
    cout << "Calculated Results:" << endl;
    cout << "  Area: " << fixed << setprecision(2) << area << endl;
    cout << endl;

    return 0;
}
